// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public {
        vm.deal(address(this), 2 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash, uint8 amountEther) public {
        uint256 amount = uint256(amountEther) * 1 ether;
        vm.assume(amount > 0);
        vm.assume(amount <= 2 ether);
        address caller = makeAddr("caller");
        vm.deal(caller, amount);
        vm.prank(caller);
        bool ok;
        try c.lockInGuess{value: amount}(hash) {
            ok = true;
        } catch {
            ok = false;
        }
        bool expectedOk = amount == 1 ether;
        assertTrue(ok == expectedOk);
    }
}
